mapper.select:
select a.area_id, a.tree_id, a.category_node_id, n.node_name as category_node_name, a.area_name, a.area_type, a.gcj02_path, a.bd09_path, a.wgs84_path, a.fill_color, a.stroke_color, a.stroke_style, a.stroke_weight, a.status, a.create_time, a.remark from biz_scene_area a left join biz_tree_node n on n.node_id = a.category_node_id and n.del_flag = '0'
a.del_flag = '0'
and a.area_name like concat('%', #{bo.areaName}, '%')
and a.area_type = #{bo.areaType}
and a.tree_id = #{bo.treeId}
and a.category_node_id = #{bo.categoryNodeId}
and a.status = #{bo.status}
order by a.create_time desc, a.area_id desc

